// The audio director: follows the game store and turns bus events into mixer calls.
// What is playing is the mixer's (mixer.ts, tested against a fake output); what makes the sound is the output
// (output.web.ts: expo-audio; output.native.ts: react-native-audio-api for effects and stingers, expo-audio for loops).
// Rules live in logic.ts (tested); cue data in manifest.ts (generated by tools/audio/build.py); docs in docs/AUDIO.md.
import { setAudioModeAsync } from 'expo-audio';
import { AppState, Platform } from 'react-native';

import { HOME_SCENES } from '../content/scenes/home';
import { cityOf, hoodIds } from '../content/cities';
import type { NeighborhoodId, PanelCue } from '../content/types';
import * as G from '../engine/game';
import { useGame } from '../store/game-store';
import { onAudio, type AudioEvent } from './bus';
import { DUCK, EXCLUSIVE_CUES, PurchaseChain, VoiceLimiter, audioHood, collectSize, musicFor, panelCue } from './logic';
import { MUSIC, SFX, STINGS, STORY, type SfxId, type StoryCueId } from './manifest';
import { createMixer, type Catalog, type Mixer } from './mixer';
import { createOutput } from './output';
import { useAudioPrefs } from './prefs';

const SKIP_FADE_MS = 400;
const STING_OUT_MS = 150; // a scene's first panel clears gameplay stingers (AU27)
const SCENES = new Map(HOME_SCENES.map((s) => [s.id, s]));

const CATALOG: Catalog = {
  sfxCount: (id) => SFX[id as SfxId].length,
  // a track this build lacks plays the Downtown bed rather than throwing (a city's own set comes with its bundle)
  music: (t) => (MUSIC[t as keyof typeof MUSIC] ?? MUSIC.downtown) as unknown as ReturnType<Catalog['music']>,
  sting: (k) => STINGS[k as keyof typeof STINGS],
  story: (id) => STORY[id as StoryCueId],
};

let started = false;
let mixer: Mixer;
let suppressed = false;
const suppressedListeners = new Set<(suppressed: boolean) => void>();

/** AU41: Music is off for this session because another app is playing (the saved preference is untouched). For Settings. */
export function musicSuppressed(): boolean {
  return suppressed;
}

/** Subscribe to `musicSuppressed()` changes; returns the unsubscribe. */
export function onMusicSuppressed(cb: (suppressed: boolean) => void): () => void {
  suppressedListeners.add(cb);
  return () => {
    suppressedListeners.delete(cb);
  };
}
const chain = new PurchaseChain();
let scenePanelCue: PanelCue = 'none';
let lastScenePanel = '';

/** The neighbourhood whose sounds `hood` plays in the open game's city (see `audioHood`). */
function soundOf(hood: NeighborhoodId): NeighborhoodId {
  return audioHood(hood, useGame.getState().game.city);
}

/** Where the stingers' key is: the open scene's neighbourhood, else the active one. */
function whereNow(): NeighborhoodId {
  const st = useGame.getState();
  return soundOf(st.playing ? st.playing.scene.neighborhood : st.game.active);
}

function refreshMusic() {
  const s = useGame.getState();
  if (!s.loaded) return; // no Downtown blip before the save says where the player is (AU44)
  const scene = s.playing ? s.playing.scene : null;
  const home = cityOf(s.game).id === 'home'; // Downtown's sparse chart is the home city's opening only
  const track = musicFor({
    active: soundOf(s.game.active),
    downtownFull: !home || s.game.seenScenes.includes('downtown-4'),
    scene: scene ? { neighborhood: soundOf(scene.neighborhood), panelCue: scenePanelCue, beat: home && typeof scene.beat === 'number' ? scene.beat : undefined } : null,
  });
  mixer.setTrack(track);
  mixer.duck('scene', scene ? DUCK.scene : null);
  mixer.duck('popup', s.offline && !scene ? DUCK.popup : null);
  // a scene's stingers are in its own key; preload there while it plays (AU43)
  mixer.scheduleStingPreload(whereNow(), whereNow);
}

// ------------------------------------------------------------------------------------------------ story panels
function onPanel(sceneId: string, panel: number) {
  const scene = SCENES.get(sceneId);
  if (!scene) return;
  const key = `${sceneId}/${panel}`;
  if (key === lastScenePanel) return;
  lastScenePanel = key;
  // a cue still waiting for the previous panel (held stinger, triumph payoff) belongs to that panel: drop it (AU57)
  mixer.clearPendingCues();
  // a scene never opens over a gameplay stinger (AU27), except the build or bid stinger that opened it (AU42)
  if (panel === 0) mixer.stopStings(STING_OUT_MS, true);
  const cue = panelCue(scene, panel);
  scenePanelCue = cue;
  refreshMusic();
  const hood = soundOf(scene.neighborhood);
  const here = () => lastScenePanel === key;
  switch (cue) {
    case 'welcome':
    case 'warmth':
      return mixer.afterHeld(() => mixer.sting(hood, cue, { gated: false }), here);
    case 'rep':
      // Dock Saved: the D-minor version over an A pedal keeps the bid's A7 hanging for the bell triumph (AU42)
      return mixer.afterHeld(() => mixer.story(scene.trigger.kind === 'bid' ? 'megaslice_rep_dock' : 'megaslice_rep', EXCLUSIVE_CUES.has('rep')), here);
    case 'victor-exit':
      return mixer.story('victor_exit', false);
    case 'triumph':
      return mixer.story(`triumph_${hood}`, true);
    case 'bell-triumph':
      return mixer.story('triumph_waterfront', true);
    case 'recipe':
      return mixer.story('recipe', true);
    case 'reunion':
      return mixer.story('reunion', true);
    case 'city-theme':
      return mixer.story('city_theme', true);
    default:
      return;
  }
}

// ------------------------------------------------------------------------------------------------ rare one-shots (AU61)
/**
 * Create the rare effects when they become relevant, so the first play isn't made at play time: the Collect
 * (the size the popup will use) while the offline popup is open, the build effect once a pizzeria can be built, the
 * gavel once the Pier 9 bid is on offer. A play releases its sound; this runs on every store update, so a build
 * that is still on offer is warmed again, and an unused Collect is released once the popup is gone.
 */
function warmRare(s: ReturnType<typeof useGame.getState>) {
  if (!s.loaded) return;
  mixer.sweepWarm(!!s.offline);
  if (!useAudioPrefs.getState().sound) return;
  if (s.offline) mixer.warm('collect', collectSize(s.offline.earned, s.game.cash), true);
  if (!mixer.loaded('build', 0) && hoodIds(cityOf(s.game)).some((id) => !G.buildLock(s.game, id))) mixer.warm('build', 0);
  if (!mixer.loaded('gavel', 0) && G.pier9Available(s.game)) mixer.warm('gavel', 0);
}

// ------------------------------------------------------------------------------------------------ events
function handle(e: AudioEvent) {
  const g = useGame.getState();
  const active = soundOf(g.game.active);
  const sceneHood = g.playing ? soundOf(g.playing.scene.neighborhood) : active;
  const now = Date.now();
  switch (e.type) {
    case 'tap':
      return mixer.sfx('tap');
    case 'full':
      return mixer.sfx('full', { jitter: 0.5 });
    case 'rush': {
      const gain = rushLimiter.hit(now);
      return gain > 0 ? mixer.sfx('rush', { gain }) : undefined;
    }
    case 'cash': {
      const gain = popLimiter.hit(now);
      return gain > 0 ? mixer.sfx('cash', { gain, jitter: 2 }) : undefined;
    }
    case 'refused':
      return mixer.sfx('refused', { jitter: 0.5 });
    case 'click':
      return mixer.sfx('click', { jitter: 0.3 });
    case 'bubble':
      return mixer.sfx('bubble', { jitter: 0.5 });
    case 'buy': {
      if (e.what === 'expand') mixer.sfx('expand', { jitter: 0.5 });
      else if (e.what === 'grade') mixer.sfx('grade', { jitter: 0.5 });
      else if (e.what === 'fleet') mixer.sfx('fleet', { variant: e.vehicle ?? 0, jitter: 0 });
      else if (e.what === 'build') mixer.sfx('build', { jitter: 0 });
      else if (e.what === 'bid') mixer.sfx('gavel', { jitter: 0 });
      else {
        const step = chain.next(now);
        mixer.sfx('buy', { variant: step, jitter: step === 0 ? 0.3 : 0 }); // AU37: slow play still varies
      }
      if (e.what === 'decor') mixer.sfx('sparkle', { jitter: 0.5 });
      if (e.sting === 'milestone' || e.sting === 'milestone_big') mixer.sfx('milestone', { jitter: 0 });
      // the bid holds a tension chord the Dock Saved scene resolves; a new pizzeria plays its own neighbourhood's motif
      if (e.what === 'bid') return mixer.sting('waterfront', 'bid', { immediate: true });
      if (e.what === 'build' && e.hood) return mixer.sting(soundOf(e.hood), 'build', { immediate: true });
      if (e.sting) mixer.sting(active, e.sting);
      return;
    }
    case 'perk':
      return mixer.perk(sceneHood);
    case 'offline-open':
      return; // played from the store subscription once the save is loaded (AU44)
    case 'collect':
      return mixer.sfx('collect', { variant: e.size, jitter: 0 });
    case 'scene-panel':
      return onPanel(e.sceneId, e.panel);
    case 'scene-skip':
      return mixer.skip(SKIP_FADE_MS);
  }
}

const popLimiter = new VoiceLimiter();
const rushLimiter = new VoiceLimiter();

/** Start the director once, at app start (root layout). Safe to call again. */
export function startAudio() {
  if (started) return;
  started = true;
  // AU24: obey the silent switch, mix with the player's own music or podcast, stop in the background
  void setAudioModeAsync({ playsInSilentMode: false, interruptionMode: 'mixWithOthers', shouldPlayInBackground: false }).catch(() => {});
  void useAudioPrefs.getState().load();
  try {
    mixer = createMixer({ out: createOutput(), catalog: CATALOG, prefs: () => useAudioPrefs.getState(),
      onSuppressed: (v) => {
        suppressed = v;
        for (const cb of [...suppressedListeners]) cb(v);
      },
    });
    mixer.boot({ unlocked: Platform.OS !== 'web' }); // web: browsers block audio until the first gesture
  } catch {
    started = false;
    return; // audio must never stop the game from starting
  }
  // the title and Downtown sets are up; the rest of the effects wait for the first frame (AU39)
  requestAnimationFrame(() => requestAnimationFrame(() => mixer.afterFirstFrame()));
  onAudio(handle);

  if (Platform.OS === 'web' && typeof document !== 'undefined') {
    const unlock = () => {
      mixer.unlock();
      document.removeEventListener('pointerdown', unlock);
      refreshMusic();
    };
    document.addEventListener('pointerdown', unlock);
  }

  let lastPlaying = useGame.getState().playing;
  let lastActive = useGame.getState().game.active;
  let lastSeen = useGame.getState().game.seenScenes.length;
  let lastOffline = useGame.getState().offline;
  let lastLoaded = useGame.getState().loaded;
  useGame.subscribe((s) => {
    warmRare(s);
    if (s.playing !== lastPlaying) {
      if (!s.playing) {
        scenePanelCue = 'none';
        lastScenePanel = '';
        mixer.clearPendingCues();
        mixer.stopStory(SKIP_FADE_MS);
      }
      lastPlaying = s.playing;
      refreshMusic();
    }
    if (s.loaded !== lastLoaded) {
      lastLoaded = s.loaded;
      refreshMusic();
    }
    if (s.game.active !== lastActive || s.game.seenScenes.length !== lastSeen || s.offline !== lastOffline) {
      // the popup's celesta in the saved neighbourhood's key, once the save is in (AU44)
      if (s.offline && !lastOffline && s.loaded) mixer.sting(soundOf(s.game.active), 'offline', { immediate: true, gated: false, duck: 1 });
      lastActive = s.game.active;
      lastSeen = s.game.seenScenes.length;
      lastOffline = s.offline;
      refreshMusic();
    }
  });
  let lastMusicPref = useAudioPrefs.getState().music;
  useAudioPrefs.subscribe((p) => {
    // a change of the Music switch is the player's own word: it ends "another app is playing" for this session (AU41)
    mixer.prefsChanged(p.music !== lastMusicPref);
    lastMusicPref = p.music;
    if (!mixer.musicOn()) mixer.musicOff();
    refreshMusic();
  });
  // Control Center or a notification makes the app `inactive`, not backgrounded: keep playing (AU54)
  AppState.addEventListener('change', (state) => {
    const was = mixer.appActive;
    mixer.setAppActive(state !== 'background');
    if (was === mixer.appActive) return;
    if (mixer.appActive) refreshMusic();
  });
  refreshMusic();
}
